    "engram.token_compress": String.raw`c_t=\operatorname{CompressTokenizer}(\mathrm{id}_t)`,
    "engram.ngram_window": String.raw`\begin{aligned}G_t^{(n)}&=(c_t,c_{t-1},\ldots,c_{t-n+1}),\\ n&\in\{2,3,4\}.\end{aligned}`,
    "engram.multihead_hash": String.raw`\begin{aligned}z_{n,h}&=\bigoplus_{i=0}^{n-1}c_{t-i}\mu_{n,h,i},\\ a_{n,h}&=o_{n,h}+(z_{n,h}\bmod p_{n,h}).\end{aligned}`,
    "engram.lookup": String.raw`e_{n,h}=\mathcal E[a_{n,h}]`,
    "engram.kv_projection": String.raw`\begin{aligned}e&=\operatorname{concat}_{n,h}(e_{n,h}),\\ [k_1,k_2,k_3,k_4,v]&=W_{kv}e.\end{aligned}`,
    "engram.gate_weights": String.raw`w_j=q^{(w)}_j\odot k^{(w)}_j,\qquad j=1,\ldots,4`,
