    "engram.inject": String.raw`X'_j=X_j+g_jv,\qquad j=1,\ldots,4`,

    "mhc.coeff_predict_attn": String.raw`\begin{aligned}z&=\operatorname{vec}(X_l),\\ r&=(\operatorname{mean}(z^2)+\varepsilon_{\mathrm{norm}})^{-1/2},\\ m&=W_Hzr,\\ A&=\sigma(s_Am_A+b_A)+\varepsilon_{\mathrm{hc}},\\ C&=2\sigma(s_Cm_C+b_C),\\ U&=s_Bm_B+b_B,\\ \widetilde B&=\operatorname{softmax}_{\mathrm{row}}(U)+\varepsilon_{\mathrm{hc}},\\ B&=\operatorname{Sinkhorn}_{20}(\widetilde B).\end{aligned}`,
    "mhc.attn_collapse": String.raw`x_{\mathrm{attn}}=\sum_{j=1}^{4}A_{\mathrm{prev},j}X_{l,j}`,
    "mhc.attn_norm": String.raw`\widehat x_{\mathrm{attn}}=\operatorname{RMSNorm}(x_{\mathrm{attn}})`,
